    def _trials(self, job: str) -> dict[str, list[Path]]:
        """task name -> its trial dirs in one Harbor job."""
        out: dict[str, list[Path]] = {}
        jd = self.jobs / job
        if not jd.is_dir():
            return out
        for t in sorted(jd.iterdir()):
